import React, { useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useMutation, gql } from '@apollo/client';
import './SettingsView.css';

const CHANGE_PASSWORD_MUTATION = gql`
  mutation ChangePassword($currentPassword: String!, $newPassword: String!) {
    changePassword(currentPassword: $currentPassword, newPassword: $newPassword)
  }
`;

const SettingsView = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [passwordErrors, setPasswordErrors] = useState({});

  const [changePassword, { loading: changingPassword }] = useMutation(CHANGE_PASSWORD_MUTATION, {
    onCompleted: () => {
      setSuccess(true);
      setError('');
      setPasswordData({ currentPassword: '', newPassword: '', confirmPassword: '' });
      setPasswordErrors({});
      setTimeout(() => {
        setSuccess(false);
      }, 3000);
    },
    onError: (err) => {
      setError(err.message || 'Failed to change password');
      setSuccess(false);
    },
  });

  const handleNotificationChange = (key) => {
    setNotifications(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handlePreferenceChange = (key, value) => {
    setPreferences(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const handlePasswordChange = (e) => {
    const { name, value } = e.target;
    setPasswordData(prev => ({ ...prev, [name]: value }));
    setError('');
    if (passwordErrors[name]) {
      setPasswordErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const validatePasswordForm = () => {
    const errors = {};
    if (!passwordData.currentPassword || passwordData.currentPassword.trim() === '') {
      errors.currentPassword = 'Current password is required';
    }
    if (!passwordData.newPassword || passwordData.newPassword.trim() === '') {
      errors.newPassword = 'New password is required';
    } else if (passwordData.newPassword.length < 6) {
      errors.newPassword = 'Password must be at least 6 characters';
    }
    if (!passwordData.confirmPassword || passwordData.confirmPassword.trim() === '') {
      errors.confirmPassword = 'Please confirm your new password';
    } else if (passwordData.newPassword !== passwordData.confirmPassword) {
      errors.confirmPassword = 'Passwords do not match';
    }
    if (passwordData.currentPassword === passwordData.newPassword) {
      errors.newPassword = 'New password must be different from current password';
    }
    return errors;
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    setError('');
    setPasswordErrors({});
    
    const errors = validatePasswordForm();
    if (Object.keys(errors).length > 0) {
      setPasswordErrors(errors);
      return;
    }

    changePassword({
      variables: {
        currentPassword: passwordData.currentPassword.trim(),
        newPassword: passwordData.newPassword.trim()
      }
    });
  };

  const handleSave = () => {
    // Save preferences/notifications (not implemented yet)
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
    }, 3000);
  };

  return (
    <div className="settings-view">
      <div className="settings-header">
        <h2>Settings</h2>
        <p className="settings-subtitle">Manage your account preferences and settings</p>
      </div>

      <div className="settings-container">
        <div className="settings-sidebar">
          <button 
            className={`settings-tab ${activeTab === 'profile' ? 'active' : ''}`}
            onClick={() => setActiveTab('profile')}
          >
            👤 Profile
          </button>
          <button 
            className={`settings-tab ${activeTab === 'preferences' ? 'active' : ''}`}
            onClick={() => setActiveTab('preferences')}
          >
            ⚙️ Preferences
          </button>
          <button 
            className={`settings-tab ${activeTab === 'notifications' ? 'active' : ''}`}
            onClick={() => setActiveTab('notifications')}
          >
            🔔 Notifications
          </button>
          <button 
            className={`settings-tab ${activeTab === 'security' ? 'active' : ''}`}
            onClick={() => setActiveTab('security')}
          >
            🔒 Security
          </button>
        </div>

        <div className="settings-content">
          {success && (
            <div className="success-message">
              <span className="success-icon">✅</span>
              <span className="success-text">Settings saved successfully!</span>
            </div>
          )}
          {activeTab === 'profile' && (
            <div className="settings-section">
              <h3>Profile Information</h3>
              <div className="settings-form">
                <div className="form-group">
                  <label>Username</label>
                  <input 
                    type="text" 
                    value={user?.username || ''} 
                    disabled
                    className="form-input"
                  />
                  <p className="form-help">Username cannot be changed</p>
                </div>
                <div className="form-group">
                  <label>Email</label>
                  <input 
                    type="email" 
                    value={user?.email || ''} 
                    disabled
                    className="form-input"
                  />
                  <p className="form-help">Email cannot be changed</p>
                </div>
                <div className="form-group">
                  <label>Role</label>
                  <input 
                    type="text" 
                    value={user?.role || ''} 
                    disabled
                    className="form-input"
                  />
                  <p className="form-help">Role is assigned by administrator</p>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'preferences' && (
            <div className="settings-section">
              <h3>Preferences</h3>
              <div className="settings-form">
                <div className="form-group">
                  <label>Theme</label>
                  <select 
                    value={preferences.theme}
                    onChange={(e) => handlePreferenceChange('theme', e.target.value)}
                    className="form-input"
                  >
                    <option value="light">Light</option>
                    <option value="dark">Dark</option>
                    <option value="auto">Auto</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Language</label>
                  <select 
                    value={preferences.language}
                    onChange={(e) => handlePreferenceChange('language', e.target.value)}
                    className="form-input"
                  >
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Timezone</label>
                  <select 
                    value={preferences.timezone}
                    onChange={(e) => handlePreferenceChange('timezone', e.target.value)}
                    className="form-input"
                  >
                    <option value="UTC">UTC</option>
                    <option value="America/New_York">Eastern Time (ET)</option>
                    <option value="America/Chicago">Central Time (CT)</option>
                    <option value="America/Denver">Mountain Time (MT)</option>
                    <option value="America/Los_Angeles">Pacific Time (PT)</option>
                  </select>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <div className="settings-section">
              <h3>Notification Preferences</h3>
              <div className="settings-form">
                <div className="checkbox-group">
                  <label className="checkbox-label">
                    <input 
                      type="checkbox"
                      checked={notifications.email}
                      onChange={() => handleNotificationChange('email')}
                      className="checkbox-input"
                    />
                    <span>Email Notifications</span>
                    <p className="checkbox-help">Receive notifications via email</p>
                  </label>
                </div>
                <div className="checkbox-group">
                  <label className="checkbox-label">
                    <input 
                      type="checkbox"
                      checked={notifications.push}
                      onChange={() => handleNotificationChange('push')}
                      className="checkbox-input"
                    />
                    <span>Push Notifications</span>
                    <p className="checkbox-help">Receive browser push notifications</p>
                  </label>
                </div>
                <div className="checkbox-group">
                  <label className="checkbox-label">
                    <input 
                      type="checkbox"
                      checked={notifications.sms}
                      onChange={() => handleNotificationChange('sms')}
                      className="checkbox-input"
                    />
                    <span>SMS Notifications</span>
                    <p className="checkbox-help">Receive notifications via SMS</p>
                  </label>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'security' && (
            <div className="settings-section">
              <h3>Security Settings</h3>
              <form onSubmit={handlePasswordSubmit} className="settings-form">
                {success && (
                  <div className="success-message">
                    <span className="success-icon">✅</span>
                    <span className="success-text">Password changed successfully!</span>
                  </div>
                )}
                {error && (
                  <div className="error-message">
                    <span className="error-icon">⚠️</span>
                    <span className="error-text">{error}</span>
                  </div>
                )}
                <div className="form-group">
                  <label>Current Password *</label>
                  <input 
                    type="password" 
                    name="currentPassword"
                    value={passwordData.currentPassword}
                    onChange={handlePasswordChange}
                    placeholder="Enter current password"
                    className={passwordErrors.currentPassword ? 'form-input input-error' : 'form-input'}
                  />
                  {passwordErrors.currentPassword && (
                    <span className="field-error-message">{passwordErrors.currentPassword}</span>
                  )}
                </div>
                <div className="form-group">
                  <label>New Password *</label>
                  <input 
                    type="password" 
                    name="newPassword"
                    value={passwordData.newPassword}
                    onChange={handlePasswordChange}
                    placeholder="Enter new password (min 6 characters)"
                    className={passwordErrors.newPassword ? 'form-input input-error' : 'form-input'}
                  />
                  {passwordErrors.newPassword && (
                    <span className="field-error-message">{passwordErrors.newPassword}</span>
                  )}
                </div>
                <div className="form-group">
                  <label>Confirm New Password *</label>
                  <input 
                    type="password" 
                    name="confirmPassword"
                    value={passwordData.confirmPassword}
                    onChange={handlePasswordChange}
                    placeholder="Confirm new password"
                    className={passwordErrors.confirmPassword ? 'form-input input-error' : 'form-input'}
                  />
                  {passwordErrors.confirmPassword && (
                    <span className="field-error-message">{passwordErrors.confirmPassword}</span>
                  )}
                  <p className="form-help">Password must be at least 6 characters long</p>
                </div>
                <div className="form-group">
                  <button 
                    type="submit" 
                    className="save-button"
                    disabled={changingPassword}
                    style={{ marginTop: '8px' }}
                  >
                    {changingPassword ? 'Changing...' : '🔒 Change Password'}
                  </button>
                </div>
              </form>
              <div className="settings-form" style={{ marginTop: '32px' }}>
                <div className="form-group">
                  <label>Two-Factor Authentication</label>
                  <div className="toggle-group">
                    <span>Enable 2FA</span>
                    <label className="toggle-switch">
                      <input type="checkbox" />
                      <span className="toggle-slider"></span>
                    </label>
                  </div>
                  <p className="form-help">Add an extra layer of security to your account</p>
                </div>
              </div>
            </div>
          )}

          {activeTab !== 'security' && (
            <div className="settings-actions">
              <button className="save-button" onClick={handleSave}>
                💾 Save Changes
              </button>
              <button className="cancel-button">
                Cancel
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SettingsView;
